import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";

import * as Separator from "../../ui/shadcn-separator";

// MODEL

export const Model = S.Struct({});

export type Model = typeof Model.Type;

// MESSAGE

export const Message = m("Message");

export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      Message: () => [model, []],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-8")],
    [
      h.div(
        [h.Class("space-y-1")],
        [
          h.h4(
            [h.Class("text-sm font-medium leading-none")],
            ["shadcn/ui"]
          ),
          h.p(
            [h.Class("text-sm font-medium text-gray-950")],
            ["The Foundation for your Design System"]
          ),
          h.p(
            [h.Class("text-sm text-gray-500")],
            [
              "A set of beautifully designed components that you can customize, extend, and build on.",
            ]
          ),
        ]
      ),
      Separator.view<Message>({ classes: "my-4" }),
      h.div(
        [h.Class("flex h-5 items-center space-x-4 text-sm")],
        [
          h.div([], ["Blog"]),
          Separator.view<Message>({ orientation: "vertical" }),
          h.div([], ["Docs"]),
          Separator.view<Message>({ orientation: "vertical" }),
          h.div([], ["Source"]),
        ]
      ),
      h.div(
        [h.Class("grid gap-4 rounded-lg border border-gray-200 p-4")],
        [
          h.div(
            [h.Class("grid gap-1")],
            [
              h.div([h.Class("font-medium text-gray-950")], ["Settings"]),
              h.div([h.Class("text-sm text-gray-500")], [
                "Manage preferences",
              ]),
            ]
          ),
          Separator.view<Message>(),
          h.div(
            [h.Class("grid gap-1")],
            [
              h.div([h.Class("font-medium text-gray-950")], ["Account"]),
              h.div([h.Class("text-sm text-gray-500")], [
                "Profile & security",
              ]),
            ]
          ),
          Separator.view<Message>(),
          h.div(
            [h.Class("grid gap-1")],
            [
              h.div([h.Class("font-medium text-gray-950")], ["Help"]),
              h.div([h.Class("text-sm text-gray-500")], [
                "Support & docs",
              ]),
            ]
          ),
        ]
      ),
      h.div(
        [h.Class("grid gap-3 rounded-lg border border-gray-200 p-4")],
        [
          h.div(
            [h.Class("flex items-center justify-between")],
            [
              h.span([h.Class("text-sm font-medium text-gray-950")], [
                "Item 1",
              ]),
              h.span([h.Class("text-sm text-gray-500")], ["Value 1"]),
            ]
          ),
          Separator.view<Message>(),
          h.div(
            [h.Class("flex items-center justify-between")],
            [
              h.span([h.Class("text-sm font-medium text-gray-950")], [
                "Item 2",
              ]),
              h.span([h.Class("text-sm text-gray-500")], ["Value 2"]),
            ]
          ),
          Separator.view<Message>(),
          h.div(
            [h.Class("flex items-center justify-between")],
            [
              h.span([h.Class("text-sm font-medium text-gray-950")], [
                "Item 3",
              ]),
              h.span([h.Class("text-sm text-gray-500")], ["Value 3"]),
            ]
          ),
        ]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as ShadcnSeparatorBasicExample from "./main";

describe("Shadcn Separator Basic example", () => {
  test("matches the shadcn separator demo content", () => {
    Scene.scene(
      {
        update: ShadcnSeparatorBasicExample.update,
        view: ShadcnSeparatorBasicExample.view,
      },
      Scene.with(ShadcnSeparatorBasicExample.init()[0]),
      Scene.expect(Scene.text("shadcn/ui")).toExist(),
      Scene.expect(
        Scene.text("The Foundation for your Design System")
      ).toExist(),
      Scene.expect(
        Scene.text(
          "A set of beautifully designed components that you can customize, extend, and build on."
        )
      ).toExist(),
      Scene.expect(Scene.text("Blog")).toExist(),
      Scene.expect(Scene.text("Docs")).toExist(),
      Scene.expect(Scene.text("Source")).toExist(),
      Scene.expect(Scene.text("Blog")).not.toHaveHandler("click"),
      Scene.expect(Scene.text("Docs")).not.toHaveHandler("click"),
      Scene.expect(Scene.text("Source")).not.toHaveHandler("click"),
      Scene.expect(Scene.text("Settings")).toExist(),
      Scene.expect(Scene.text("Manage preferences")).toExist(),
      Scene.expect(Scene.text("Account")).toExist(),
      Scene.expect(Scene.text("Profile & security")).toExist(),
      Scene.expect(Scene.text("Help")).toExist(),
      Scene.expect(Scene.text("Support & docs")).toExist(),
      Scene.expect(Scene.text("Item 1")).toExist(),
      Scene.expect(Scene.text("Value 1")).toExist(),
      Scene.expect(Scene.text("Item 2")).toExist(),
      Scene.expect(Scene.text("Value 2")).toExist(),
      Scene.expect(Scene.text("Item 3")).toExist(),
      Scene.expect(Scene.text("Value 3")).toExist(),
      Scene.expect(Scene.role("button", { name: "Toggle label" })).not.toExist()
    );
  });
});
